do local TargetPlaceId=84305192589317;if (game.PlaceId~=TargetPlaceId) then game:GetService("StarterGui"):SetCore("SendNotification",{Title="Error de Juego",Text="Este script solo funciona en CHAMBERED DUELS!",Duration=6.5});return;end local Success,Library=pcall(function() return loadstring(game:HttpGet("https://github.com/bkkpro1980/InfilSense-Lib-v2/releases/latest/download/build.lua"))();end);if ( not Success or  not Library) then return;end local app=Library.new({Name="Chambered Duels Pro",SaveFolder="ChamberedConfigs",SaveId="default"});local Players=game:GetService("Players");local RunService=game:GetService("RunService");local Workspace=game:GetService("Workspace");local Stats=game:GetService("Stats");local LocalPlayer=Players.LocalPlayer;local Camera=Workspace.CurrentCamera;local AimbotEnabled=false;local SelectedPart="Head";local WallCheckEnabled=false;local TeamCheckEnabled=true;local FOVEnabled=false;local FOVRadius=120;local ESPEnabled=false;local ESPBox=false;local ESPLine=false;local ESPSkeleton=false;local ESPText=false;local TeamColorESP=true;local HitboxVisualizer=false;local WatermarkEnabled=false;local FPSPingEnabled=false;local TargetInfoEnabled=false;local CustomCrosshairEnabled=false;local SpeedEnabled=false;local NoclipEnabled=false;local FOVCircle=Drawing.new("Circle");FOVCircle.Visible=false;FOVCircle.Transparency=0.8;FOVCircle.Thickness=2;FOVCircle.Color=Color3.fromRGB(0,255,255);FOVCircle.Filled=false;FOVCircle.Radius=FOVRadius;local CustomCrosshair=Drawing.new("Circle");CustomCrosshair.Visible=false;CustomCrosshair.Radius=4;CustomCrosshair.Filled=true;CustomCrosshair.Color=Color3.fromRGB(255,255,255);CustomCrosshair.Transparency=0.9;local WatermarkText=Drawing.new("Text");WatermarkText.Visible=false;WatermarkText.Size=16;WatermarkText.Color=Color3.fromRGB(255,255,255);WatermarkText.Outline=true;WatermarkText.Position=Vector2.new(30,30);local FPSPingText=Drawing.new("Text");FPSPingText.Visible=false;FPSPingText.Size=16;FPSPingText.Color=C