et Information",Description="Muestra la salud y nombre del objetivo actual."},InternalInfo={Toggle=true,UniqueCommandId="target_info_toggle"},Callback=function(enabled) TargetInfoEnabled=enabled;TargetInfoText.Visible=enabled;end});movementTab:AddButton({Info={Title="Activar Speed Boost",Description="Aumenta la velocidad de movimiento a 50."},InternalInfo={Toggle=true,UniqueCommandId="speed_boost_toggle"},Callback=function(enabled) SpeedEnabled=enabled;if ( not enabled and LocalPlayer.Character) then local hum=LocalPlayer.Character:FindFirstChildOfClass("Humanoid");if hum then hum.WalkSpeed=16;end end end});movementTab:AddButton({Info={Title="Activar Noclip",Description="Permite atravesar paredes y obstáculos."},InternalInfo={Toggle=true,UniqueCommandId="noclip_toggle"},Callback=function(enabled) NoclipEnabled=enabled;end});local function getTargetPart(character) if (SelectedPart=="Head") then return character:FindFirstChild("Head");elseif (SelectedPart=="Torso") then return character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Torso") or character:FindFirstChild("UpperTorso") ;elseif (SelectedPart=="Foot") then return character:FindFirstChild("RightFoot") or character:FindFirstChild("LeftFoot") or character:FindFirstChild("Right Leg") ;end return character:FindFirstChild("Head");end local function isVisible(targetPart) if  not WallCheckEnabled then return true;end local origin=Camera.CFrame.Position;local direction=targetPart.Position-origin ;local raycastParams=RaycastParams.new();raycastParams.FilterType=RaycastParams.FilterType.Blacklist;raycastParams.FilterDescendantsInstances={LocalPlayer.Character,Camera};raycastParams.IgnoreWater=true;local result=Workspace:Raycast(origin,direction,raycastParams);if result then return result.Instance:IsDescendantOf(targetPart.Parent);end return true;end local lastTick=tick();local frameCount=0;local currentFPS=60;RunService.RenderStepped:Connect(function() frameCount=frameCount + 1 ;local currentTick=tick