;end if ESPText then e.NameDist.Text=player.Name   .. " ["   .. math.floor(distance)   .. "m]" ;e.NameDist.Position=Vector2.new(rootPos.X,rootPos.Y-45 );e.NameDist.Visible=true;else e.NameDist.Visible=false;end if (ESPSkeleton and head and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"))) then local torso=character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") ;local la=character:FindFirstChild("LeftUpperArm") or character:FindFirstChild("Left Arm") ;local ra=character:FindFirstChild("RightUpperArm") or character:FindFirstChild("Right Arm") ;local ll=character:FindFirstChild("LeftUpperLeg") or character:FindFirstChild("Left Leg") ;local rl=character:FindFirstChild("RightUpperLeg") or character:FindFirstChild("Right Leg") ;local function connectParts(p1,p2,lineObj) if (p1 and p2) then local pos1,vis1=Camera:WorldToViewportPoint(p1.Position);local pos2,vis2=Camera:WorldToViewportPoint(p2.Position);if (vis1 and vis2) then lineObj.From=Vector2.new(pos1.X,pos1.Y);lineObj.To=Vector2.new(pos2.X,pos2.Y);lineObj.Color=renderColor;lineObj.Visible=true;return;end end lineObj.Visible=false;end connectParts(head,torso,e.HeadToNeck);connectParts(torso,rootPart,e.NeckToTorso);connectParts(torso,la,e.LeftArm);connectParts(torso,ra,e.RightArm);connectParts(rootPart,ll,e.LeftLeg);connectParts(rootPart,rl,e.RightLeg);else for _,bone in pairs({e.HeadToNeck,e.NeckToTorso,e.LeftArm,e.RightArm,e.LeftLeg,e.RightLeg}) do bone.Visible=false;end end else e.Box.Visible=false;e.Line.Visible=false;e.NameDist.Visible=false;for _,bone in pairs({e.HeadToNeck,e.NeckToTorso,e.LeftArm,e.RightArm,e.LeftLeg,e.RightLeg}) do bone.Visible=false;end end else removeESP(player);end if (humanoid and (humanoid.Health>0) and  not isTeamMate) then local targetPart=getTargetPart(character);if (targetPart and isVisible(targetPart)) then local screenPoint,onScreen=Camera:WorldToViewportPoint(targetPart.Position);if onScreen then local screenPos2D=Vector2.new(screenPoi